fn to_uppercase(str1: &Vec<char>) -> Vec<char> {
    // Preallocate a vector of the same length as the input
    let mut result = Vec::with_capacity(str1.len());

    // For each character, convert ASCII lowercase to uppercase;
    // leave all other characters unchanged.
    for &c in str1.iter() {
        if c.is_ascii_lowercase() {
            result.push(c.to_ascii_uppercase());
        } else {
            result.push(c);
        }
    }

    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty() {
        let input: Vec<char> = vec![];
        let output = to_uppercase(&input);
        assert!(output.is_empty());
    }

    #[test]
    fn test_all_lowercase() {
        let input: Vec<char> = "abcdefxyz".chars().collect();
        let output = to_uppercase(&input);
        let expected: Vec<char> = "ABCDEFXYZ".chars().collect();
        assert_eq!(output, expected);
    }

    #[test]
    fn test_mixed_ascii() {
        let input: Vec<char> = "Hello, World! 123".chars().collect();
        let output = to_uppercase(&input);
        let expected: Vec<char> = "HEllo, WorlD! 123".chars().collect();
        // Note: only 'e','l','l','o','o','r','l','d' would be lower→upper
        // but 'H','W' remain as they were uppercase already.
        assert_eq!(output, expected);
    }

    #[test]
    fn test_non_ascii() {
        let input: Vec<char> = "héllo Привет こんにちは".chars().collect();
        let output = to_uppercase(&input);
        // Only ASCII 'h','e','l','l','o' get uppercased;
        // accented and non-Latin letters remain unchanged.
        let expected: Vec<char> = "HÉLLO Привет こんにちは".chars().collect();
        assert_eq!(output, expected);
    }
}